mapper.select:
select

from corgi_vlog v

    left join corgi_activity_like l on l.activity_id = v.activity_id

where not exists(select 1 from corgi_feed_${index} f where f.user_id = #{vlog.userId} and f.feed =
v.activity_id)
  and v.user_id != #{vlog.userId}

    and v.ctime <= #{vlog.ctime}


    and l.like_user_id in (select co_user_id from corgi_user_coordinate where user_id = #{vlog.userId})

order by v.ctime desc limit #{size}

select

from corgi_vlog v
where not exists(select 1 from corgi_feed_${index} f where f.user_id = #{vlog.userId} and f.feed =
v.activity_id)
and user_id = #{userId}

    and ctime <= #{vlog.ctime}

order by v.like_count desc limit #{size}

select

from corgi_vlog v
where v.user_id in (select follow_user_id from corgi_user_follow where user_id = #{userId})
and v.ctime <=#{ctime}
order by v.id desc
limit #{start}, #{size}

select

from corgi_vlog v
where v.user_id = #{userId}
and v.ctime <=#{ctime}
order by v.id desc
limit #{start}, #{size}

mapper.update:
update corgi_vlog
set status = 'failed'
where activity_id = #{activityId}

update corgi_vlog_hot


        `like_count` = like_count + ${vlog.likeCount},


        `view_count` = view_count + ${vlog.viewCount},


        `expect_view` = #{vlog.expect_view}


        `status` = #{vlog.status}


where

    `id` = #{vlog.id}


    activity_id = #{vlog.activityId}

mapper.select:
select id, activity_id activityId, like_count likeCount, view_count viewCount, expect_view expectView, ctime, `status`, uptime from corgi_vlog_hot where 1=1
and `type` = #{vlog.type}
and `status` = #{vlog.status}
and `activity_id` = #{activityId}
order by id desc limit #{start}, #{size}

select count(1)
from corgi_vlog_hot where 1=1

    and `type` = #{vlog.type}


    and `status` = #{vlog.status}


    and `activity_id` = #{activityId}
